import '@servicenow/sdk/global'
import { StringColumn, IntegerColumn } from '@servicenow/sdk/core'
import { action, Flow, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for SetFlowVariables with datapills
 * Tests: trigger, flow_variable, and action output datapills
 */
export const setFlowVariablesDatapills = Flow(
    {
        $id: Now.ID['set-flow-variables-datapills'],
        name: 'SetFlowVariables Datapills Test',
        description: 'Test SetFlowVariables with various datapill types',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            maxThreshold: IntegerColumn({
                label: 'Max Threshold',
                mandatory: false,
            }),
            incidentPriority: IntegerColumn({
                label: 'Incident Priority',
                mandatory: false,
            }),
            threshold: IntegerColumn({
                label: 'Threshold',
                mandatory: false,
            }),
            actionResult: StringColumn({
                label: 'Action Result',
                mandatory: false,
            }),
            summary: StringColumn({
                label: 'Summary',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-datapills-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Execute action to get outputs for datapill testing
        const actionResult = wfa.action(
            action.core.log,
            {
                $id: Now.ID['test-action-instance-1'],
                uuid: 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee',
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(params.trigger.current.sys_id, 'string'),
            }
        )

        // Test 1: SetFlowVariables with trigger datapill
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-trigger-pill'],
                annotation: 'Set variables with trigger datapills',
            },
            params.flowVariables,
            {
                incidentPriority: wfa.dataPill(params.trigger.current.priority, 'integer'),
            }
        )

        // Test 2: SetFlowVariables with flow variable datapill
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-flowvar-pill'],
                annotation: 'Set variables with flow variable datapills',
            },
            params.flowVariables,
            {
                threshold: wfa.dataPill(params.flowVariables.maxThreshold, 'integer'),
            }
        )

        // Test 3: SetFlowVariables with action output datapill
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-action-pill'],
                annotation: 'Set variables with action output datapills',
            },
            params.flowVariables,
            {
                actionResult: wfa.dataPill(actionResult.__action_status__, 'integer'),
            }
        )

        // Test 4: SetFlowVariables with template expression
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-template'],
                annotation: 'Set variables with template expressions',
            },
            params.flowVariables,
            {
                summary: `Priority: ${wfa.dataPill(params.trigger.current.priority, 'integer')}, Threshold: ${wfa.dataPill(params.flowVariables.maxThreshold, 'integer')}`,
            }
        )
    }
)
